"use client";

import Link from "next/link";
import { StudySet } from "@/lib/types";
import { LayersIcon, BookOpenIcon, TrashIcon } from "@/components/icons";

interface SetsListProps {
  sets: StudySet[];
  onDelete: (id: string) => void;
}

export default function SetsList({ sets, onDelete }: SetsListProps) {
  return (
    <div className="w-full max-w-[760px] border-t-[3px] border-[#263fd6] pt-3.5">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <LayersIcon className="h-3.5 w-3.5 text-[#d8f56d]" />
          <h2 className="font-heading text-base font-semibold text-[#172b35]">
            Your sets
          </h2>
        </div>
        {sets.length > 0 && (
          <p className="font-body text-xs text-[#5d6f74]">
            {sets.length} saved to your account
          </p>
        )}
      </div>

      {sets.length === 0 ? (
        <div className="mt-5 border border-dashed border-[#9bb8bc] bg-white py-10 text-center text-[#5d6f74]">
          No sets yet. Upload your first photo above.
        </div>
      ) : (
        <ul className="mt-3.5 grid grid-cols-1 gap-3 sm:grid-cols-2">
          {sets.map((set) => (
            <li
              key={set.id}
                className="min-h-[176px] border border-[#dce4bd] bg-[#F7FAE7] p-6 shadow-[4px_4px_0_#e5ecec]"
            >
              <div className="flex items-start justify-between gap-2">
                <p className="font-heading text-xl font-semibold text-[#172b35]">
                  {set.name}
                </p>
                <button
                  onClick={() => onDelete(set.id)}
                  className="shrink-0 rounded-full p-1.5 text-[#5d6f74] hover:bg-[#eef1ff] hover:text-[#263fd6]"
                  aria-label="Delete set"
                >
                  <TrashIcon className="h-4 w-4" />
                </button>
              </div>
              <p className="font-body pt-1.5 text-[11px] text-[#5d6f74]">
                {set.words.length} words · {set.masteredWordIds.length} mastered
              </p>
              <Link
                href={`/sets/${set.id}`}
                className="mt-3 inline-flex h-7 items-center gap-1.5 rounded-full bg-[#d8f56d] px-3 text-[11px] font-medium text-[#172b35]"
              >
                <BookOpenIcon className="h-3 w-3" /> Study
              </Link>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
