"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import UploadCard from "@/components/UploadCard";
import SetsList from "@/components/SetsList";
import { addSet, deleteSet, loadSets } from "@/lib/storage";
import { extractVocabFromImages } from "@/lib/extractVocab";
import { deriveSetName } from "@/lib/naming";
import { EXERCISE_SET_ID } from "@/lib/exerciseData";
import { StudySet } from "@/lib/types";

export default function Home() {
  const [sets, setSets] = useState<StudySet[]>([]);
  const [notice, setNotice] = useState<string | null>(null);

  useEffect(() => {
    setSets(loadSets());
  }, []);

  const handleCreateSet = async (files: File[]) => {
    const { topic, words, usedFallback } = await extractVocabFromImages(files);
    const newSet: StudySet = {
      id: crypto.randomUUID(),
      name: deriveSetName(files, sets.length, topic),
      createdAt: Date.now(),
      sourceImageCount: files.length,
      words: words.map((w) => ({ id: crypto.randomUUID(), ...w })),
      masteredWordIds: [],
    };
    setSets(addSet(newSet));
    setNotice(
      usedFallback
        ? "Couldn't reach the Ollama vision model, so this set uses placeholder vocabulary. Make sure `ollama serve` is running with the llava model pulled."
        : null
    );
  };

  const handleDelete = (id: string) => {
    setSets(deleteSet(id));
  };

  return (
    <main
      className="relative flex flex-1 flex-col items-center bg-white px-4 pb-16 pt-8"
    >
      <div className="flex flex-col items-center gap-4 text-center">
        <h1 className="font-heading text-4xl leading-tight tracking-[-1px] text-[#172b35]">
          Learn B2 Beruf Deutsch Vocabulary
        </h1>

        <p className="font-body max-w-[460px] text-[13px] leading-5 text-[#60747a]">
          Photograph a textbook page, a menu or a street sign. Lexikon pulls out
          the German vocabulary, adds English translations, and builds four ways
          to practise it.
        </p>
      </div>

      <div className="mt-7 flex w-full flex-col items-center gap-4">
        <UploadCard onCreateSet={handleCreateSet} />
        {notice && (
          <p className="max-w-lg rounded-xl border border-[#b9c9eb] bg-[#eef1ff] px-4 py-3 text-center text-sm text-[#172b35]">
            {notice}
          </p>
        )}
        <Link
          href={`/sets/${EXERCISE_SET_ID}`}
          className="text-sm text-[#263fd6] underline-offset-4 hover:text-[#1d2fb5] hover:underline"
        >
          View an example study set →
        </Link>
        <SetsList sets={sets} onDelete={handleDelete} />
      </div>
    </main>
  );
}
